import Foundation
#if canImport(Security)
import Security
#endif

/// The two passwords slop-export ever needs. Both are generated by David's own tools
/// (Bridge's IMAP password, an iCloud app-specific password); neither is his account password.
public enum SecretKind: String, Sendable, CaseIterable {
    case bridge
    case icloud

    /// Keychain service name.
    public var service: String { "slop-export.\(rawValue)" }
    /// Environment variable used on Linux test runs and in CI.
    public var environmentVariable: String { "SLOP_\(rawValue.uppercased())_PASSWORD" }
}

public enum SecretError: Error, CustomStringConvertible {
    case missing(SecretKind, account: String)
    case keychain(OSStatusCode: Int32)

    public var description: String {
        switch self {
        case .missing(let kind, let account):
            #if canImport(Security)
            return "No \(kind.rawValue) password saved for \(account). Save it in the app's Connect step, or set \(kind.environmentVariable)."
            #else
            return "No \(kind.rawValue) password: set \(kind.environmentVariable)."
            #endif
        case .keychain(let status):
            return "Keychain error \(status)."
        }
    }
}

public protocol SecretStore: Sendable {
    func password(_ kind: SecretKind, account: String) throws -> String?
}

/// Reads `SLOP_BRIDGE_PASSWORD` / `SLOP_ICLOUD_PASSWORD`. Never from command-line arguments,
/// which end up in shell history and `ps`.
public struct EnvironmentSecrets: SecretStore {
    private let environment: [String: String]
    public init(environment: [String: String] = ProcessInfo.processInfo.environment) {
        self.environment = environment
    }
    public func password(_ kind: SecretKind, account: String) throws -> String? {
        environment[kind.environmentVariable].flatMap { $0.isEmpty ? nil : $0 }
    }
}

#if canImport(Security)
/// Generic-password items in the login Keychain, service `slop-export.<kind>`, account = user name.
public struct KeychainSecrets: SecretStore {
    public init() {}

    public func password(_ kind: SecretKind, account: String) throws -> String? {
        let query: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: kind.service,
            kSecAttrAccount as String: account,
            kSecReturnData as String: true,
            kSecMatchLimit as String: kSecMatchLimitOne,
        ]
        var item: CFTypeRef?
        let status = SecItemCopyMatching(query as CFDictionary, &item)
        if status == errSecItemNotFound { return nil }
        guard status == errSecSuccess, let data = item as? Data else { throw SecretError.keychain(OSStatusCode: status) }
        return String(decoding: data, as: UTF8.self)
    }

    public func setPassword(_ password: String, _ kind: SecretKind, account: String) throws {
        let base: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: kind.service,
            kSecAttrAccount as String: account,
        ]
        let data = Data(password.utf8)
        var status = SecItemUpdate(base as CFDictionary, [kSecValueData as String: data] as CFDictionary)
        if status == errSecItemNotFound {
            var add = base
            add[kSecValueData as String] = data
            add[kSecAttrAccessible as String] = kSecAttrAccessibleWhenUnlockedThisDeviceOnly
            add[kSecAttrLabel as String] = "slop-export \(kind.rawValue) password"
            status = SecItemAdd(add as CFDictionary, nil)
        }
        guard status == errSecSuccess else { throw SecretError.keychain(OSStatusCode: status) }
    }

    public func deletePassword(_ kind: SecretKind, account: String) throws {
        let query: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: kind.service,
            kSecAttrAccount as String: account,
        ]
        let status = SecItemDelete(query as CFDictionary)
        guard status == errSecSuccess || status == errSecItemNotFound else { throw SecretError.keychain(OSStatusCode: status) }
    }
}
#endif

/// Environment first (tests, CI), then the Keychain on macOS.
public struct DefaultSecrets: SecretStore {
    public init() {}
    public func password(_ kind: SecretKind, account: String) throws -> String? {
        if let value = try EnvironmentSecrets().password(kind, account: account) { return value }
        #if canImport(Security)
        return try KeychainSecrets().password(kind, account: account)
        #else
        return nil
        #endif
    }

    public func require(_ kind: SecretKind, account: String) throws -> String {
        guard let value = try password(kind, account: account) else { throw SecretError.missing(kind, account: account) }
        return value
    }
}
